import{_ as i,C as r,o as n,c as h,j as d,a as e,E as o,a5 as c}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"切换按钮组","description":"","frontmatter":{},"headers":[],"relativePath":"components/toggle-group.md","filePath":"components/toggle-group.md","lastUpdated":1787598366000}'),g={name:"components/toggle-group.md"},s={id:"切换按钮组",tabindex:"-1"};function u(p,t,b,m,x,f){const l=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",s,[t[0]||(t[0]=e("切换按钮组 ",-1)),o(l,{type:"info",text:"toggle-group"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#切换按钮组","aria-label":'Permalink to "切换按钮组 <Badge type="info" text="toggle-group" />"'},"​",-1))]),t[3]||(t[3]=c('<p>一排连在一起的切换按钮，整组共一个值：单选时是分段控件，多选时是一排可同时按下的工具钮。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>在少数几个互斥项之间切换视图（日 / 周 / 月，列表 / 网格）。</li><li>一排可同时开关的格式工具（加粗 / 斜体 / 下划线），此时开 <code>multiple</code>。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>选项超过五六个，或需要搜索：用<a href="./select">选择器</a>。</li><li>选项要随表单提交并需要 label 关联：用<a href="./radio-group">单选组</a>。</li><li>各段是动作不是选项：用<a href="./button-group">按钮组</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>multiple</code> 换的是整套 ARIA：单选时 <code>root</code> 是 <code>radiogroup</code>、条目是 <code>radio</code>；多选时 <code>root</code> 退回 <code>group</code>、条目退回按钮加 <code>aria-pressed</code>，值也从字符串变成数组。</li><li>roving tabindex：整组只占一个 Tab 位，进组后四个方向键都能走，与视觉排布无关。</li><li><code>disallowEmpty</code> 决定能不能点成空值。</li><li>条目一律 <code>aria-disabled</code> 而非原生 <code>disabled</code>：点不动但焦点落得上去，仍能当方向键的起点。</li><li>给了 <code>collection</code> 就由它做显示文本与禁用的事实源，条目部件只需报 <code>value</code>。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>单选分段控件：root 是 radiogroup、条目是 radio；整组只占一个 Tab 位，进组后四个方向键都能走</p>',10)),o(a,{src:"toggle-group/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控与不可清空",tabindex:"-1"},[e("受控与不可清空 "),d("a",{class:"header-anchor",href:"#受控与不可清空","aria-label":'Permalink to "受控与不可清空"'},"​")],-1)),t[5]||(t[5]=d("p",null,"传了 value 就由宿主说了算；单选组再点一次当前项会清空成 null，disallow-empty 把这一手关掉",-1)),o(a,{src:"toggle-group/02-controlled"}),t[6]||(t[6]=d("h3",{id:"多选",tabindex:"-1"},[e("多选 "),d("a",{class:"header-anchor",href:"#多选","aria-label":'Permalink to "多选"'},"​")],-1)),t[7]||(t[7]=d("p",null,"multiple 换的是整套 ARIA：root 退回 group、条目退回原生按钮 + aria-pressed，值也从字符串变成数组",-1)),o(a,{src:"toggle-group/03-multiple"}),t[8]||(t[8]=d("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[9]||(t[9]=d("p",null,"条目一律 aria-disabled 而非原生 disabled：点不动，但焦点落得上去，仍能当方向键的起点",-1)),o(a,{src:"toggle-group/04-disabled"}),t[10]||(t[10]=d("h3",{id:"条目增删",tabindex:"-1"},[e("条目增删 "),d("a",{class:"header-anchor",href:"#条目增删","aria-label":'Permalink to "条目增删"'},"​")],-1)),t[11]||(t[11]=d("p",null,"条目集合在运行期可增可删，增删后照常接线；删掉的正好是选中项时由宿主把值收拾干净",-1)),o(a,{src:"toggle-group/05-dynamic-items"}),t[12]||(t[12]=d("h3",{id:"拦下一次切换",tabindex:"-1"},[e("拦下一次切换 "),d("a",{class:"header-anchor",href:"#拦下一次切换","aria-label":'Permalink to "拦下一次切换"'},"​")],-1)),t[13]||(t[13]=d("p",null,"受控时 value-change 是唯一出口：宿主不写回，值就原样不动，条件不满足的那一段永远切不过去",-1)),o(a,{src:"toggle-group/06-guard"}),t[14]||(t[14]=d("h3",{id:"整组换一档尺寸",tabindex:"-1"},[e("整组换一档尺寸 "),d("a",{class:"header-anchor",href:"#整组换一档尺寸","aria-label":'Permalink to "整组换一档尺寸"'},"​")],-1)),t[15]||(t[15]=d("p",null,"高度、内边距与字号各是一个组件令牌，写在 root 上由整组条目继承，不必逐个条目改",-1)),o(a,{src:"toggle-group/07-size"}),t[16]||(t[16]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-toggle-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhToggleGroupItem</code> <code>XhToggleGroupRoot</code></td></tr><tr><td>组合式函数</td><td><code>useToggleGroup</code></td></tr><tr><td>状态机</td><td><code>toggleGroupMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/toggle-group.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;toggle-group&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>ToggleGroupNode[]</code></td><td></td><td>条目数据，显示文本与禁用的事实源。给了它，条目部件只需报 value。 缺省即回到「文本与禁用都写在条目部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>ToggleGroupValue</code></td><td></td><td>选中值。给定即受控：内部不再自改，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>ToggleGroupValue</code></td><td></td><td></td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td></td><td>允许多项同时选中；false 时选中一项即挤掉其余。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组禁用：条目全部 aria-disabled，点击与方向键都不生效。</td></tr><tr><td><code>disallowEmpty</code></td><td><code>boolean</code></td><td></td><td>不许把值清空：单选模式下点当前选中项不再取消它，多选模式下摘不掉最后一个。 默认 false（可以点成无选中）。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>视觉排布，默认 horizontal。方向键接受的轴与它无关（四个方向键恒响应）。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只改写左右方向键的语义，上下键与之无关。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>rovingFocus</code></td><td><code>boolean</code></td><td></td><td>roving tabindex，默认开启：整组只占一个 Tab 位，组内靠方向键走。 关掉后每个条目自成一个 Tab 停靠点，方向键不再接管。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: ToggleGroupValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>ToggleGroupValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | string[] | null }</code>（形态跟着 multiple 走）</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>&#39;on&#39; | &#39;off&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.TOGGLE</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useToggleGroup</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string[]</code></td><td>当前选中集合，恒为数组（单选时长度 ≤ 1）。</td></tr><tr><td><code>collection</code></td><td><code>readonly ToggleGroupNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: ToggleGroupValue) =&gt; void</code></td><td>传单值 / 数组 / null 皆可，内部按 multiple 归一。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: ToggleGroupItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>rovingFocus 开启（默认）</td><td>整组只占一个 Tab 位：焦点落到锚点条目，无锚点时先落容器再由它转投</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in group, 组未禁用且 rovingFocus 开启</td><td>焦点移到下一个可停留条目（禁用项跳过、尽头按 loop 回绕），不改选中；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in group, 组未禁用且 rovingFocus 开启</td><td>焦点移到上一个可停留条目，不改选中；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Home</code></td><td>focus in group, 组未禁用且 rovingFocus 开启</td><td>焦点移到首个可停留条目</td></tr><tr><td><code>End</code></td><td>focus in group, 组未禁用且 rovingFocus 开启</td><td>焦点移到末个可停留条目</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, 条目未禁用</td><td>切换该条目；条目是原生 button，这两个键由平台翻成 click</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>undefined | props.orientation</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39; | &#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>undefined | &#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-pressed</code></td><td>&#39;true&#39; | &#39;false&#39; | undefined</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>undefined | &#39;radio&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/toggle-group.css</code> 按部件选择：<code>[data-scope=&quot;toggle-group&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;on&#39; | &#39;off&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-toggle-group-item-bg</code> · <code>--xh-toggle-group-item-bg-active</code> · <code>--xh-toggle-group-item-bg-disabled</code> · <code>--xh-toggle-group-item-bg-hover</code> · <code>--xh-toggle-group-item-bg-on</code> · <code>--xh-toggle-group-item-bg-on-active</code> · <code>--xh-toggle-group-item-bg-on-hover</code> · <code>--xh-toggle-group-item-border</code> · <code>--xh-toggle-group-item-border-disabled</code> · <code>--xh-toggle-group-item-border-on</code> · <code>--xh-toggle-group-item-border-on-disabled</code> · <code>--xh-toggle-group-item-fg</code> · <code>--xh-toggle-group-item-fg-disabled</code> · <code>--xh-toggle-group-item-fg-on</code> · <code>--xh-toggle-group-item-fg-on-disabled</code> · <code>--xh-toggle-group-item-font-size</code> · <code>--xh-toggle-group-item-font-weight</code> · <code>--xh-toggle-group-item-gap</code> · <code>--xh-toggle-group-item-h</code> · <code>--xh-toggle-group-item-px</code> · <code>--xh-toggle-group-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./toolbar">工具栏</a>嵌套：工具栏管跨组导航，本组管组内。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>段数固定在二到五段，段宽尽量等长，切换时整条不该变宽。</li><li>单选组默认允许点空；表单里当必填项用时把 <code>disallowEmpty</code> 打开。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿它当<a href="./tabs">标签页</a>用：标签页有面板关联（<code>aria-controls</code>）与相应的读屏语义，切换按钮组没有。</li><li>关掉 <code>rovingFocus</code> 却不另给导航方式：每段自成一个 Tab 停靠点，键盘用户要按很多次才能走完。</li></ul>',44))])}const T=i(g,[["render",u]]);export{P as __pageData,T as default};
